package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.Jsoup;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;

public class Attribute_getValue_TriageGen2Test {

    @Test
    public void testGetValue_Normal() {
        // Arrange
        Document doc = Jsoup.parse("<div id='test'>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = element.attr("id");

        // Act
        String value = attr.getValue();

        // Assert
        assertEquals("test", value);
    }

    @Test
    public void testGetValue_Null() {
        // Arrange
        Document doc = Jsoup.parse("<div>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = element.attr("id");
        attr.setKey(null);

        // Act
        String value = attr.getValue();

        // Assert
        assertNull(value);
    }

    @Test
    public void testGetValue_Empty() {
        // Arrange
        Document doc = Jsoup.parse("<div>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = element.attr("id");
        attr.setKey("");

        // Act
        String value = attr.getValue();

        // Assert
        assertEquals("", value);
    }

    @Test
    public void testGetValue_NullKey() {
        // Arrange
        Document doc = Jsoup.parse("<div>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = new Attribute(null, "value");

        // Act
        String value = attr.getValue();

        // Assert
        assertEquals("value", value);
    }

    @Test
    public void testGetValue_NullValue() {
        // Arrange
        Document doc = Jsoup.parse("<div>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = new Attribute("key", null);

        // Act
        String value = attr.getValue();

        // Assert
        assertNull(value);
    }

    @Test
    public void testGetValue_NullKeyAndValue() {
        // Arrange
        Document doc = Jsoup.parse("<div>Hello</div>");
        Element element = doc.getElementById("test");
        Attribute attr = new Attribute(null, null);

        // Act
        String value = attr.getValue();

        // Assert
        assertNull(value);
    }
}
